$codesDir = "scripts/codes"

function Write-Template($id, $title, $desc, $cat, $stars, $author, $views, $updated, $html) {
  $meta = "$id|$title|$desc|$cat|$stars|$author|$views|$updated"
  $b64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($html))
  Set-Content -Path "$codesDir/$id.txt" -Value ($meta + "`n" + $b64) -NoNewline
  Write-Host "  $id ($($b64.Length) chars)"
}

Write-Template 'blog-magazine' 'DevBlog Pro' 'Modern tech blog with article search, category filter tabs, sort options, reading progress bar, and responsive card grid with author metadata.' 'Blogs' 389 'BlogStudio' '7.2k' '1 week ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DevBlog</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#f8fafc;color:#1e293b}.dark body{background:#0f172a;color:#e2e8f0}.prog{position:fixed;top:0;left:0;height:3px;background:linear-gradient(90deg,#3b82f6,#8b5cf6);z-index:100;width:0}.w{max-width:900px;margin:0 auto;padding:24px}hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}hdr h1 span{color:#3b82f6}.tb{background:none;border:1px solid #e2e8f0;border-radius:6px;padding:6px 12px;cursor:pointer;font-size:.8rem;color:#1e293b}.dark .tb{border-color:#334155;color:#e2e8f0}.ctrls{display:flex;gap:12px;margin-bottom:20px}input,select{padding:8px 12px;border:1px solid #e2e8f0;border-radius:6px;font-size:.8rem;outline:none;background:#fff;color:#1e293b}.dark input,.dark select{background:#1e293b;border-color:#334155;color:#e2e8f0}input:focus,select:focus{border-color:#3b82f6}input{flex:1}.cat{display:flex;gap:8px;margin-bottom:20px;flex-wrap:wrap}.cat button{padding:6px 14px;border:1px solid #e2e8f0;border-radius:99px;background:none;cursor:pointer;font-size:.8rem;color:#64748b}.dark .cat button{border-color:#334155;color:#94a3b8}.cat button.active,.cat button:hover{background:#3b82f6;color:#fff;border-color:#3b82f6}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}.a{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:20px}.dark .a{background:#1e293b;border-color:#334155}.a .cb{display:inline-block;padding:2px 8px;border-radius:4px;font-size:.7rem;font-weight:600;margin-bottom:8px;background:#3b82f610;color:#3b82f6}.a h3{font-size:1rem;margin-bottom:6px}.a p{font-size:.8rem;color:#64748b;margin-bottom:12px}.dark .a p{color:#94a3b8}.a .m{display:flex;justify-content:space-between;font-size:.75rem;color:#94a3b8;border-top:1px solid #e2e8f0;padding-top:12px}.dark .a .m{border-color:#334155}</style></head><body><div class="prog" id="prog"></div><div class="w"><hdr><h1>Dev<span>Blog</span></h1><button class="tb" id="tb" onclick="tog()">Dark</button></hdr><div class="ctrls"><input id="sIn" placeholder="Search..." oninput="filt()"><select id="sSel" onchange="filt()"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="title">Title</option></select></div><div class="cat"><button class="active" onclick="setC(&#39;all&#39;,this)">All</button><button onclick="setC(&#39;backend&#39;,this)">Backend</button><button onclick="setC(&#39;frontend&#39;,this)">Frontend</button><button onclick="setC(&#39;devops&#39;,this)">DevOps</button></div><div class="grid" id="g"></div></div><script>var arts=[{t:"Rust vs Go: A Comparison",e:"Detailed analysis of both languages for systems programming.",c:"backend",a:"Alex Rivera",d:"2026-06-08",r:"8 min"},{t:"CSS Container Queries",e:"How to use container queries for responsive components.",c:"frontend",a:"Maya Patel",d:"2026-06-06",r:"6 min"},{t:"K8s Deployment Strategies",e:"Blue-green, canary, rolling updates.",c:"devops",a:"Jordan Lee",d:"2026-06-04",r:"10 min"},{t:"TypeScript 5.5 Features",e:"New features including inferred type predicates.",c:"frontend",a:"Alex Rivera",d:"2026-05-30",r:"5 min"},{t:"WebAssembly for Web Devs",e:"Leverage WASM for performance-critical code.",c:"frontend",a:"Sam Wilson",d:"2026-05-28",r:"9 min"},{t:"Microservices with Go",e:"Guide to designing distributed systems.",c:"backend",a:"Sarah Chen",d:"2026-06-01",r:"12 min"}];var cc="all";function r(l){var g=document.getElementById("g");if(!l.length){g.innerHTML="<p style='color:#94a3b8;text-align:center;padding:40px'>No articles</p>";return}g.innerHTML=l.map(function(a){return'<div class="a"><span class="cb">'+a.c+'</span><h3>'+a.t+'</h3><p>'+a.e+'</p><div class="m"><span>'+a.a+'</span><span>'+new Date(a.d).toLocaleDateString()+" | "+a.r+"</span></div></div>"}).join("")}window.filt=function(){var l=[].concat(arts),q=document.getElementById("sIn").value.toLowerCase(),s=document.getElementById("sSel").value;if(q)l=l.filter(function(a){return a.t.toLowerCase().includes(q)||a.e.toLowerCase().includes(q)});if(cc!=="all")l=l.filter(function(a){return a.c===cc});if(s==="title")l.sort(function(a,b){return a.t.localeCompare(b.t)});else if(s==="oldest")l.sort(function(a,b){return a.d.localeCompare(b.d)});else l.sort(function(a,b){return b.d.localeCompare(a.d)});r(l)};window.setC=function(c,b){document.querySelectorAll(".cat button").forEach(function(x){x.classList.remove("active")});b.classList.add("active");cc=c;filt()};window.tog=function(){document.body.classList.toggle("dark");document.getElementById("tb").textContent=document.body.classList.contains("dark")?"Light":"Dark"};window.addEventListener("scroll",function(){var h=document.documentElement.scrollHeight-window.innerHeight,p=(window.scrollY/h)*100;document.getElementById("prog").style.width=p+"%"});filt()</script></body></html>
