<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SocialFlow</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0}.w{max-width:600px;margin:0 auto;padding:24px}.logo{font-size:1.25rem;font-weight:700;background:linear-gradient(135deg,#d946ef,#3b82f6);-webkit-background-clip:text;-webkit-text-fill-color:transparent}.cmp{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:16px;margin-bottom:20px}.cmp textarea{width:100%;background:none;border:none;color:#e2e8f0;font-size:.9rem;resize:none;outline:none;min-height:60px;font-family:inherit}.cmp .ft{display:flex;justify-content:space-between;align-items:center;margin-top:8px;padding-top:12px;border-top:1px solid #334155}.cmp .ft .cnt{font-size:.75rem;color:#64748b}.cmp .ft .cnt.w{color:#f59e0b}.cmp .ft .cnt.o{color:#ef4444}.cmp .ft button{padding:8px 20px;background:#d946ef;border:none;border-radius:8px;color:#fff;font-weight:600;font-size:.8rem;cursor:pointer}.cmp .ft button:disabled{opacity:0.5}.p{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:16px;margin-bottom:16px}.p .hd{display:flex;align-items:center;gap:10px;margin-bottom:10px}.p .av{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700}.p .bd{font-size:.9rem;line-height:1.5;margin-bottom:12px}.p .ac{display:flex;gap:4px;border-top:1px solid #334155;padding-top:10px}.p .ac button{flex:1;background:none;border:none;padding:6px;border-radius:6px;cursor:pointer;color:#64748b;font-size:.8rem;display:flex;align-items:center;justify-content:center;gap:4px}.p .ac button:hover{background:#334155}.p .ac button.l{color:#ef4444}.ov{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:#00000060;z-index:199}.ov.s{display:block}.sh{display:none;position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1e293b;border:1px solid #334155;border-radius:12px;padding:24px;z-index:200;width:300px;text-align:center}.sh.s{display:block}</style></head><body><div class="w"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px"><span class="logo">SocialFlow</span></div><div class="cmp"><textarea id="pIn" placeholder="What's happening?" maxlength="280" oninput="upd()"></textarea><div class="ft"><span class="cnt" id="cc">0/280</span><button id="pBtn" onclick="cr()">Post</button></div></div><div id="feed"></div></div><div class="ov" id="ov" onclick="clSh()"></div><div class="sh" id="sh"><h3>Share</h3><div style="display:flex;gap:8px;justify-content:center;margin-top:12px"><button style="padding:8px 16px;border:1px solid #334155;border-radius:8px;background:none;color:#e2e8f0;cursor:pointer" onclick="shP('Twitter')">Twitter</button><button style="padding:8px 16px;border:1px solid #334155;border-radius:8px;background:none;color:#e2e8f0;cursor:pointer" onclick="shP('FB')">Facebook</button><button style="padding:8px 16px;border:1px solid #334155;border-radius:8px;background:none;color:#e2e8f0;cursor:pointer" onclick="clSh()">Cancel</button></div></div><script>var posts=[{id:1,au:"Alice Chen",ha:"@alicecodes",co:"#3b82f6",tx:"Just deployed my first K8s cluster! The learning curve is steep but the power is incredible.",lk:24,ld:false},{id:2,au:"Maya Patel",ha:"@mayadesigns",co:"#d946ef",tx:"CSS container queries will change frontend development more than any framework.",lk:18,ld:false},{id:3,au:"Jordan Lee",ha:"@jordanml",co:"#10b981",tx:"Fine-tuned LLM for code gen hit 90% accuracy. AI-assisted dev is here.",lk:35,ld:false}];var nid=4;function rd(){document.getElementById("feed").innerHTML=posts.map(function(p){return'<div class="p"><div class="hd"><div class="av" style="background:'+p.co+'20;color:'+p.co+'">'+p.au[0]+'</div><div><div style="font-weight:600;font-size:.85rem">'+p.au+'</div><div style="font-size:.75rem;color:#64748b">'+p.ha+"</div></div></div><div class=\"bd\">"+p.tx+'</div><div class="ac"><button class="'+(p.ld?"l":"")+'" onclick="tog('+p.id+')">'+(p.ld?"Liked":"Like")+" "+p.lk+'</button><button onclick="opSh('+p.id+')">Share</button></div></div>'}).join("")}window.upd=function(){var i=document.getElementById("pIn"),c=document.getElementById("cc"),b=document.getElementById("pBtn"),l=i.value.length;c.textContent=l+"/280";c.className="cnt"+(l>250?" w":"")+(l>=280?" o":"");b.disabled=l===0||l>280};window.cr=function(){var i=document.getElementById("pIn"),t=i.value.trim();if(!t)return;posts.unshift({id:nid++,au:"You",ha:"@you",co:"#f59e0b",tx:t,lk:0,ld:false});i.value="";upd();rd()};window.tog=function(id){var p=posts.find(function(x){return x.id===id});if(p){p.ld=!p.ld;p.lk+=p.ld?1:-1;rd()}};window.opSh=function(){document.getElementById("ov").classList.add("s");document.getElementById("sh").classList.add("s")};window.clSh=function(){document.getElementById("ov").classList.remove("s");document.getElementById("sh").classList.remove("s")};window.shP=function(p){alert("Shared to "+p);clSh()};rd();upd()</script></body></html>
