<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kanban Flow</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0;min-height:100vh}.w{max-width:1100px;margin:0 auto;padding:24px}hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}hdr h1 span{color:#d946ef}.add{padding:8px 16px;background:#d946ef;border:none;border-radius:8px;color:#fff;font-weight:600;cursor:pointer}.b{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.col{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:12px;min-height:300px}.col h2{font-size:.85rem;margin-bottom:12px;display:flex;justify-content:space-between}.col h2 .c{padding:1px 8px;background:#334155;border-radius:99px;font-size:.7rem;color:#94a3b8}.cd{background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;margin-bottom:8px;cursor:grab}.cd:hover{border-color:#d946ef40}.cd.d{opacity:0.5}.cd .ttl{font-size:.85rem;margin-bottom:6px}.cd .m{display:flex;justify-content:space-between;font-size:.7rem;color:#64748b}.cd .pr{padding:1px 6px;border-radius:4px;font-size:.65rem;font-weight:600}.pr.h{background:#ef444420;color:#ef4444}.pr.m{background:#f59e0b20;color:#f59e0b}.pr.l{background:#22c55e20;color:#22c55e}.cd .dl{color:#ef4444;cursor:pointer;background:none;border:none}.ov{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:#00000060;z-index:100}.ov.s{display:block}.md{display:none;position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1e293b;border:1px solid #334155;border-radius:12px;padding:24px;width:90%;max-width:360px;z-index:101}.md.s{display:block}.md input,.md select{width:100%;padding:8px 12px;background:#0f172a;border:1px solid #334155;border-radius:6px;color:#e2e8f0;font-size:.85rem;outline:none;margin-bottom:12px}.md .bx{display:flex;gap:8px;justify-content:flex-end}.md .bx button{padding:8px 16px;border-radius:6px;font-size:.8rem;cursor:pointer;font-weight:600}.md .bx .sv{background:#d946ef;border:none;color:#fff}.md .bx .cn{background:none;border:1px solid #334155;color:#94a3b8}@media(max-width:800px){.b{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.b{grid-template-columns:1fr}}</style></head><body><div class="w"><hdr><h1>Kanban<span>Flow</span></h1><button class="add" onclick="opM()">+ Add</button></hdr><div class="b" id="board"></div></div><div class="ov" id="ov" onclick="clM()"></div><div class="md" id="md"><h3>New Task</h3><input id="tT" placeholder="Title"><select id="tP"><option value="m">Medium</option><option value="h">High</option><option value="l">Low</option></select><div class="bx"><button class="cn" onclick="clM()">Cancel</button><button class="sv" onclick="svT()">Add</button></div></div><script>var cols=[{id:"bl",ttl:"Backlog"},{id:"td",ttl:"To Do"},{id:"pg",ttl:"In Progress"},{id:"dn",ttl:"Done"}];var tasks=JSON.parse(localStorage.getItem("kb")||"[]");var dragged=null;function svLS(){localStorage.setItem("kb",JSON.stringify(tasks))}function rd(){document.getElementById("board").innerHTML=cols.map(function(c){var ct=tasks.filter(function(t){return t.col===c.id});return'<div class="col" ondragover="e.preventDefault()" ondrop="dp(event,\''+c.id+'\')"><h2>'+c.ttl+' <span class="c">'+ct.length+"</span></h2>"+ct.map(function(t){return'<div class="cd" draggable="true" data-id="'+t.id+'" ondragstart="st(event)" ondragend="en(event)"><div class="ttl">'+t.t+'</div><div class="m"><span class="pr '+(t.p==="h"?"h":t.p==="m"?"m":"l")+'">'+t.p+'</span><button class="dl" onclick="dl('+t.id+')">X</button></div></div>'}).join("")+"</div>"}).join("")}window.st=function(e){dragged=e.target.closest(".cd");if(dragged)dragged.classList.add("d");e.dataTransfer.effectAllowed="move"};window.en=function(){if(dragged)dragged.classList.remove("d");dragged=null};window.dp=function(e,cid){e.preventDefault();if(!dragged)return;var id=parseInt(dragged.dataset.id),t=tasks.find(function(x){return x.id===id});if(t){t.col=cid;svLS();rd()}};window.dl=function(id){tasks=tasks.filter(function(t){return t.id!==id});svLS();rd()};window.opM=function(){document.getElementById("ov").classList.add("s");document.getElementById("md").classList.add("s")};window.clM=function(){document.getElementById("ov").classList.remove("s");document.getElementById("md").classList.remove("s")};window.svT=function(){var t=document.getElementById("tT").value.trim();if(!t)return;tasks.push({id:Date.now(),t:t,p:document.getElementById("tP").value,col:"bl"});svLS();rd();clM();document.getElementById("tT").value=""};if(!tasks.length){tasks=[{id:1,t:"Design landing",p:"h",col:"pg"},{id:2,t:"Set up CI/CD",p:"m",col:"td"},{id:3,t:"Write API docs",p:"l",col:"bl"},{id:4,t:"Fix login bug",p:"h",col:"pg"},{id:5,t:"Deploy staging",p:"m",col:"td"},{id:6,t:"Q1 Review",p:"m",col:"dn"}];svLS()}rd()</script></body></html>
"@

