<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SecureAuth</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:linear-gradient(135deg,#0f172a,#1e293b);min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px}.card{background:#1e293b;border:1px solid #334155;border-radius:16px;padding:32px;width:100%;max-width:400px}.tbs{display:flex;background:#0f172a;border-radius:10px;padding:4px;margin-bottom:24px}.tbs button{flex:1;padding:8px;border:none;background:none;color:#64748b;font-weight:600;font-size:.85rem;cursor:pointer;border-radius:8px}.tbs button.active{background:#22c55e;color:#0f172a}.tb{display:none}.tb.active{display:block}.fg{margin-bottom:16px}.fg label{display:block;font-size:.8rem;color:#94a3b8;margin-bottom:6px}.fg input,.fg select{width:100%;padding:10px 14px;background:#0f172a;border:1px solid #334155;border-radius:8px;color:#e2e8f0;font-size:.9rem;outline:none}.fg input:focus{border-color:#22c55e}.pw{position:relative}.pw input{padding-right:40px}.pw .tg{position:absolute;right:10px;top:50%;transform:translateY(-50%);background:none;border:none;color:#64748b;cursor:pointer}.st{display:flex;gap:4px;margin-top:6px}.st .sg{flex:1;height:4px;background:#334155;border-radius:2px}.st .sg.f1{background:#ef4444}.st .sg.f2{background:#f59e0b}.st .sg.f3{background:#22c55e}.stt{font-size:.75rem;margin-top:4px;color:#64748b}.btn{width:100%;padding:11px;background:#22c55e;border:none;border-radius:8px;color:#fff;font-weight:700;font-size:.9rem;cursor:pointer;margin-top:8px}.btn:disabled{opacity:0.5}.err{font-size:.75rem;color:#ef4444;margin-top:2px;display:none}.err.s{display:block}.dv{display:flex;align-items:center;gap:12px;margin:20px 0;color:#64748b;font-size:.8rem}.dv:before,.dv:after{content:'';flex:1;height:1px;background:#334155}.sc{display:grid;grid-template-columns:1fr 1fr;gap:8px}.sc button{padding:8px;background:#0f172a;border:1px solid #334155;border-radius:8px;cursor:pointer;color:#e2e8f0;font-size:.8rem}</style></head><body><div class="card"><div class="tbs"><button class="active" onclick="sw('login',this)">Sign In</button><button onclick="sw('signup',this)">Sign Up</button></div><div class="tb active" id="t-login"><form onsubmit="return hL(event)"><div class="fg"><label>Email</label><input type="email" id="le" placeholder="you@example.com"></div><div class="fg"><label>Password</label><div class="pw"><input type="password" id="lp" placeholder="Password"><button type="button" class="tg" onclick="tv('lp',this)">Show</button></div></div><button class="btn" type="submit">Sign In</button><div class="dv">or</div><div class="sc"><button type="button">Google</button><button type="button">GitHub</button></div></form></div><div class="tb" id="t-signup"><form onsubmit="return hS(event)"><div class="fg"><label>Name</label><input type="text" id="sn" placeholder="John"><div class="err" id="snE">Required</div></div><div class="fg"><label>Email</label><input type="email" id="se" placeholder="you@example.com"><div class="err" id="seE">Valid email required</div></div><div class="fg"><label>Password</label><div class="pw"><input type="password" id="sp" placeholder="Password" oninput="ck()"><button type="button" class="tg" onclick="tv('sp',this)">Show</button></div><div class="st" id="stM"><div class="sg"></div><div class="sg"></div><div class="sg"></div></div><div class="stt" id="stT">Weak</div></div><button class="btn" type="submit" id="sBtn">Create</button></form></div></div><script>window.sw=function(t,b){document.querySelectorAll(".tbs button").forEach(function(x){x.classList.remove("active")});b.classList.add("active");document.querySelectorAll(".tb").forEach(function(x){x.classList.remove("active")});document.getElementById("t-"+t).classList.add("active")};window.tv=function(id,b){var i=document.getElementById(id);if(i.type==="password"){i.type="text";b.textContent="Hide"}else{i.type="password";b.textContent="Show"}};window.hL=function(e){e.preventDefault();alert("Signed in!")};window.ck=function(){var p=document.getElementById("sp").value,s=0;if(p.length>=6)s++;if(p.length>=10)s++;if(/[A-Z]/.test(p)&&/[0-9]/.test(p))s++;var g=document.querySelectorAll("#stM .sg"),t=document.getElementById("stT");g.forEach(function(x,i){x.className="sg"+(i<s?" f"+s:"")});t.textContent=s<=1?"Weak":s===2?"Medium":"Strong"};window.hS=function(e){e.preventDefault();alert("Account created!")}</script></body></html>
