Write-Template 'chat-app' 'ChatSync Live Chat' 'Real-time chat interface with message sending, typing indicator, online status dots, emoji reactions, contact list, and simulated replies.' 'Chat/Messaging' 489 'ChatSync' '8.5k' '4 days ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ChatSync</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0;display:flex;height:100vh}.sb{width:250px;background:#1e293b;border-right:1px solid #334155;display:flex;flex-direction:column}.sb .h{padding:16px;border-bottom:1px solid #334155;font-weight:700;color:#2dd4bf}.cl{flex:1;overflow-y:auto}.c{display:flex;align-items:center;gap:10px;padding:10px 16px;cursor:pointer}.c:hover,.c.a{background:#334155}.c .av{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;position:relative}.c .av .st{position:absolute;bottom:0;right:0;width:10px;height:10px;border-radius:50%;border:2px solid #1e293b}.c .av .st.on{background:#10b981}.c .av .st.off{background:#64748b}.mn{flex:1;display:flex;flex-direction:column}.ch{padding:12px 20px;border-bottom:1px solid #334155;font-weight:600}.ms{flex:1;overflow-y:auto;padding:16px 20px;display:flex;flex-direction:column;gap:8px}.msg{max-width:75%;padding:10px 14px;border-radius:14px;font-size:.85rem}.msg.me{align-self:flex-end;background:#2dd4bf;color:#0f172a;border-bottom-right-radius:4px}.msg.th{align-self:flex-start;background:#1e293b;border:1px solid #334155;border-bottom-left-radius:4px}.msg .tm{font-size:.65rem;color:#94a3b8;margin-top:4px;display:block;text-align:right}.ty{font-size:.8rem;color:#64748b;font-style:italic;padding:4px 20px;min-height:24px}.inp{display:flex;gap:8px;padding:12px 20px;border-top:1px solid #334155;background:#1e293b}.inp input{flex:1;padding:10px 14px;background:#0f172a;border:1px solid #334155;border-radius:10px;color:#e2e8f0;font-size:.85rem;outline:none}.inp button{padding:10px 14px;background:#2dd4bf;border:none;border-radius:10px;color:#0f172a;font-weight:700;cursor:pointer}</style></head><body><div class="sb"><div class="h">ChatSync</div><div class="cl" id="cl"></div></div><div class="mn"><div class="ch" id="cNm">Sarah Chen</div><div class="ms" id="ms"></div><div class="ty" id="ty"></div><div class="inp"><input id="mIn" placeholder="Type..." oninput="onTy()" onkeydown="if(event.key==='Enter')snd()"><button onclick="snd()">Send</button></div></div><script>var ct=[{id:1,nm:"Sarah Chen",on:true,co:"#2dd4bf"},{id:2,nm:"Alex Rivera",on:true,co:"#3b82f6"},{id:3,nm:"Maya Patel",on:false,co:"#d946ef"},{id:4,nm:"Jordan Lee",on:false,co:"#10b981"}];var cur=ct[0],msgs={1:[{tx:"Hey! How's the project?",s:"th"},{tx:"Going great!",s:"me"},{tx:"Awesome!",s:"th"}]},ti=null;function rdC(){document.getElementById("cl").innerHTML=ct.map(function(c){return'<div class="c'+(c.id===cur.id?" a":"")+'" onclick="sl('+c.id+')"><div class="av" style="background:'+c.co+'20;color:'+c.co+'">'+c.nm[0]+'<span class="st '+(c.on?"on":"off")+'"></span></div><div style="font-size:.85rem">'+c.nm+"</div></div>"}).join("")}function rdM(id){if(!msgs[id])msgs[id]=[];var d=document.getElementById("ms");d.innerHTML=msgs[id].map(function(m){return'<div class="msg '+(m.s==="me"?"me":"th")+'">'+m.tx+'<span class="tm">'+m.tm+"</span></div>"}).join("");d.scrollTop=d.scrollHeight}window.sl=function(id){cur=ct.find(function(x){return x.id===id});document.getElementById("cNm").textContent=cur.nm;rdC();rdM(id)};window.snd=function(){var i=document.getElementById("mIn"),t=i.value.trim();if(!t)return;if(!msgs[cur.id])msgs[cur.id]=[];msgs[cur.id].push({tx:t,s:"me",tm:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})});i.value="";rdM(cur.id);document.getElementById("ty").textContent="";setTimeout(function(){if(cur.id===1){msgs[1].push({tx:"Perfect! I'll check it out.",s:"th",tm:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})});rdM(1)}},2000)};window.onTy=function(){document.getElementById("ty").textContent=cur.nm+" is typing...";clearTimeout(ti);ti=setTimeout(function(){document.getElementById("ty").textContent=""},1500)};rdC();rdM(cur.id)</script></body></html>
