<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cloud Console</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:'Courier New',monospace}body{background:#0d1117;color:#e6edf3}.w{max-width:1100px;margin:0 auto;padding:24px}hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}hdr h1{color:#38bdf8}.rg{padding:4px 12px;background:#38bdf820;border:1px solid #38bdf840;border-radius:6px;font-size:.75rem;color:#38bdf8}.st{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.s{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:14px}.s .l{font-size:.7rem;color:#8b949e;text-transform:uppercase}.s .v{font-size:1.2rem;font-weight:700;margin-top:4px}.s .v.gr{color:#3fb950}.s .v.bl{color:#38bdf8}.s .v.yl{color:#d29922}.rg2{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px}.rc{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:14px;display:flex;justify-content:space-between;align-items:center}.rc .dot{width:8px;height:8px;border-radius:50%}.dot.r{background:#3fb950;box-shadow:0 0 6px #3fb950}.dot.s{background:#f85149}.dot.p{background:#d29922}.tm{background:#0d1117;border:1px solid #30363d;border-radius:8px;padding:16px;font-size:.8rem;margin-bottom:20px;min-height:100px;max-height:150px;overflow-y:auto}.tm .l{color:#8b949e;margin-bottom:2px}.tm .l.p{color:#38bdf8}.tm .l.o{color:#e6edf3}.ac{display:flex;gap:8px;flex-wrap:wrap}.ac button{padding:8px 14px;background:#21262d;border:1px solid #30363d;border-radius:6px;color:#e6edf3;font-family:inherit;font-size:.8rem;cursor:pointer}.ac button:hover{background:#30363d;border-color:#38bdf8}.ac button.pr{background:#38bdf8;color:#0d1117;border-color:#38bdf8;font-weight:600}.ac button.dg{color:#f85149}.ac button.dg:hover{border-color:#f85149}@media(max-width:700px){.st,.rg2{grid-template-columns:1fr}}</style></head><body><div class="w"><hdr><h1>Cloud Console</h1><span class="rg">us-east-1</span></hdr><div class="st"><div class="s"><div class="l">Instances</div><div class="v gr">12</div></div><div class="s"><div class="l">CPU Avg</div><div class="v yl">42%</div></div><div class="s"><div class="l">Memory</div><div class="v bl">6.8GB</div></div><div class="s"><div class="l">Deploys</div><div class="v gr">24</div></div></div><div class="rg2" id="res"></div><div class="tm" id="tm"><div class="l p">user@cloud:~$ <span>Welcome</span></div></div><div class="ac"><button class="pr" onclick="dep()">Deploy</button><button onclick="rst()">Restart</button><button onclick="lgs()">Logs</button><button class="dg" onclick="stp()">Stop</button></div></div><script>var res=[{n:"web-prod-01",d:"t3.medium",st:"r"},{n:"db-primary",d:"r6g.large",st:"r"},{n:"cache-01",d:"8GB",st:"r"},{n:"worker-queue",d:"t3.small",st:"p"},{n:"staging-api",d:"t3.medium",st:"s"}];function tw(t){var d=document.getElementById("tm"),l=document.createElement("div");l.className="l o";l.textContent="> "+t;d.appendChild(l);d.scrollTop=d.scrollHeight}function rdR(){document.getElementById("res").innerHTML=res.map(function(r){return'<div class="rc"><div><div>'+r.n+'</div><div style="font-size:.75rem;color:#8b949e">'+r.d+'</div></div><div class="dot '+(r.st==="r"?"r":r.st==="s"?"s":"p")+'"></div></div>'}).join("")}window.dep=function(){tw("Deploying v2.4.1...");setTimeout(function(){tw("Build successful");setTimeout(function(){tw("Deployed!")},800)},1200)};window.rst=function(){tw("Restarting...");setTimeout(function(){tw("OK (2.1s)")},1500)};window.lgs=function(){tw("Fetching logs...");setTimeout(function(){tw("[INFO] Health check passed");tw("[INFO] Request rate: 2.4k/s")},1000)};window.stp=function(){if(confirm("Stop?")){tw("Stopping...");setTimeout(function(){tw("Stopped")},1200)}};rdR()</script></body></html>
