Write-Template 'ai-ml-dashboard' 'AI/ML Model Monitor' 'AI model monitoring dashboard with live accuracy/loss canvas charts, model status cards, dataset stats, and retrain simulation button.' 'AI/ML' 378 'MLViz' '6.7k' '1 week ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ML Monitor</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0}.w{max-width:1100px;margin:0 auto;padding:24px}hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}hdr h1 span{color:#a855f7}.mg{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px}.mc{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:16px;position:relative}.mc .tag{position:absolute;top:12px;right:12px;padding:2px 8px;border-radius:4px;font-size:.65rem;font-weight:600}.tag.pr{background:#10b98120;color:#10b981}.tag.st{background:#f59e0b20;color:#f59e0b}.tag.dv{background:#3b82f620;color:#3b82f6}.mc .ttl{font-size:.9rem;margin-bottom:4px}.mc .m{font-size:.75rem;color:#64748b}.mc .v{font-size:1rem;font-weight:600}.cr{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px}.cc{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:16px}.cc h3{color:#94a3b8;font-size:.75rem;margin-bottom:8px}canvas{width:100%!important;height:180px!important}.dt{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:16px}.dt .h{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.dr{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #334155;font-size:.85rem}.btn-t{padding:8px 16px;background:linear-gradient(135deg,#a855f7,#d946ef);border:none;border-radius:8px;color:#fff;font-weight:600;font-size:.8rem;cursor:pointer}@media(max-width:700px){.mg,.cr{grid-template-columns:1fr}}</style></head><body><div class="w"><hdr><h1>ML <span>Monitor</span></h1></hdr><div class="mg"><div class="mc"><span class="tag pr">Prod</span><div class="ttl">GPT-Neo</div><div class="m">Accuracy</div><div class="v" style="color:#10b981">94.2%</div><div class="m">Latency: 142ms</div></div><div class="mc"><span class="tag st">Stage</span><div class="ttl">CodeGen</div><div class="m">Accuracy</div><div class="v" style="color:#f59e0b">89.7%</div><div class="m">Latency: 98ms</div></div><div class="mc"><span class="tag dv">Dev</span><div class="ttl">Vision-T</div><div class="m">Accuracy</div><div class="v" style="color:#3b82f6">76.4%</div><div class="m">Epoch 12/50</div></div></div><div class="cr"><div class="cc"><h3>Training Accuracy</h3><canvas id="aC"></canvas></div><div class="cc"><h3>Loss Curve</h3><canvas id="lC"></canvas></div></div><div class="dt"><div class="h"><h3>Datasets</h3><button class="btn-t" onclick="tr()">Retrain</button></div><div class="dr"><span>Code Corpus</span><span>142K</span></div><div class="dr"><span>Documentation</span><span>89K</span></div><div class="dr"><span>Bug Reports</span><span>34K</span></div></div></div><script>function dw(id,data,col){var c=document.getElementById(id);if(!c)return;var ctx=c.getContext("2d"),dpr=window.devicePixelRatio||1,r=c.parentElement.getBoundingClientRect();c.width=r.width*dpr;c.height=180*dpr;c.style.width=r.width+"px";c.style.height="180px";ctx.scale(dpr,dpr);var w=r.width,h=180,cw=w-40,ch=h-20,mx=Math.max.apply(null,data),grd=ctx.createLinearGradient(0,10,0,170);grd.addColorStop(0,col+"40");grd.addColorStop(1,col+"00");ctx.beginPath();data.forEach(function(v,i){var x=20+i/(data.length-1)*cw,y=10+ch-v/mx*ch;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});data.forEach(function(v,i){ctx.lineTo(20+i/(data.length-1)*cw,10+ch)});ctx.closePath();ctx.fillStyle=grd;ctx.fill();ctx.beginPath();data.forEach(function(v,i){var x=20+i/(data.length-1)*cw,y=10+ch-v/mx*ch;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});ctx.strokeStyle=col;ctx.lineWidth=2;ctx.stroke()}dw("aC",[65,72,78,82,85,88,90,91.5,92.8,93.5,94,94.2],"#a855f7");dw("lC",[2.8,2.1,1.6,1.2,0.9,0.7,0.55,0.45,0.38,0.32,0.28,0.25],"#ef4444");window.tr=function(){var b=event.target;b.textContent="Training...";b.disabled=true;setTimeout(function(){b.textContent="Done!";setTimeout(function(){b.textContent="Retrain";b.disabled=false},2000)},3000)}</script></body></html>
