Write-Template 'weather-app' 'WeatherViz Live' 'Interactive weather dashboard with city search, current conditions display, 7-day forecast cards, animated weather icons, and temperature toggle.' 'Weather' 267 'WeatherDev' '4.2k' '2 days ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WeatherViz</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:linear-gradient(135deg,#0f172a,#1e293b);color:#e2e8f0;min-height:100vh}.w{max-width:700px;margin:0 auto;padding:32px 24px}h1{font-size:1.5rem;margin-bottom:20px;text-align:center}h1 span{color:#7dd3fc}.sb{display:flex;gap:8px;margin-bottom:24px;justify-content:center}.sb input{padding:10px 16px;background:#1e293b;border:1px solid #334155;border-radius:10px;color:#e2e8f0;font-size:.9rem;outline:none;width:250px}.sb input:focus{border-color:#7dd3fc}.sb button{padding:10px 20px;background:#7dd3fc;color:#0f172a;border:none;border-radius:10px;font-weight:600;cursor:pointer}.curr{background:#1e293b;border:1px solid #334155;border-radius:16px;padding:28px;text-align:center;margin-bottom:24px}.curr .temp{font-size:4rem;font-weight:700;margin:8px 0}.curr .temp span{font-size:1.5rem;color:#94a3b8;font-weight:400;cursor:pointer}.curr .cond{font-size:1.1rem;color:#7dd3fc;margin-bottom:8px}.curr .loc{font-size:.85rem;color:#64748b}.curr .dtls{display:flex;justify-content:center;gap:24px;margin-top:16px;font-size:.85rem;color:#94a3b8}.fc{display:grid;grid-template-columns:repeat(7,1fr);gap:8px}.day{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:12px;text-align:center}.day .dn{font-size:.75rem;color:#94a3b8;margin-bottom:6px}.day .ic{font-size:1.5rem;margin-bottom:4px}.day .hi{font-size:.85rem;font-weight:600}.day .lo{font-size:.75rem;color:#64748b}@media(max-width:500px){.fc{grid-template-columns:repeat(4,1fr)}}</style></head><body><div class="w"><h1>Weather<span>Viz</span></h1><div class="sb"><input id="cityIn" placeholder="Enter city..." onkeydown="if(event.key==='Enter')src()"><button onclick="src()">Search</button></div><div class="curr" id="curr"><div class="loc" id="loc">Loading...</div></div><div class="fc" id="fc"></div></div><script>var data={n:"New York",t:22,u:"C",c:"Partly Cloudy",h:65,w:12,fc:[{d:"Mon",h:22,l:16,c:"c"},{d:"Tue",h:24,l:17,c:"s"},{d:"Wed",h:21,l:15,c:"r"},{d:"Thu",h:23,l:16,c:"c"},{d:"Fri",h:25,l:18,c:"s"},{d:"Sat",h:26,l:19,c:"s"},{d:"Sun",h:24,l:17,c:"c"}]};function rd(){var c=document.getElementById("curr");c.innerHTML='<div class="loc" id="loc">'+data.n+'</div><div class="cond">'+data.c+'</div><div class="temp">'+(data.u==="C"?data.t:Math.round(data.t*9/5+32))+'&deg;<span onclick="togU()">'+data.u+'</span></div><div class="dtls"><span>Humidity: '+data.h+'%</span><span>Wind: '+data.w+' km/h</span></div>';var f=document.getElementById("fc");f.innerHTML=data.fc.map(function(d){return'<div class="day"><div class="dn">'+d.d+'</div><div class="ic">'+(d.c==="c"?"&#9729;":d.c==="s"?"&#9728;":"&#9730;")+'</div><div class="hi">'+(data.u==="C"?d.h:Math.round(d.h*9/5+32))+'&deg;</div><div class="lo">'+(data.u==="C"?d.l:Math.round(d.l*9/5+32))+'&deg;</div></div>'}).join("")}window.src=function(){var q=document.getElementById("cityIn").value.trim();if(!q)return;data.n=q;data.t=Math.floor(Math.random()*15+15);rd();document.getElementById("cityIn").value=""};window.togU=function(){data.u=data.u==="C"?"F":"C";rd()};rd()</script></body></html>
