Write-Template 'pricing-page' 'Pricing Page Pro' 'Modern SaaS pricing page with monthly/yearly toggle, feature comparison table, highlighted recommended plan, and CTA buttons.' 'SaaS' 345 'PricePro' '6.1k' '1 week ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pricing</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0}.w{max-width:900px;margin:0 auto;padding:48px 24px;text-align:center}h1{font-size:2rem;margin-bottom:8px}h1 span{color:#6366f1}.sub{color:#94a3b8;margin-bottom:32px}.tr{display:flex;align-items:center;gap:12px;justify-content:center;margin-bottom:40px}.tr span{font-size:.9rem;color:#94a3b8;cursor:pointer}.tr span.act{color:#e2e8f0;font-weight:600}.tg{width:48px;height:26px;background:#334155;border-radius:13px;cursor:pointer;position:relative}.tg.act{background:#6366f1}.tg .k{width:20px;height:20px;background:#fff;border-radius:50%;position:absolute;top:3px;left:3px;transition:transform .3s}.tg.act .k{transform:translateX(22px)}.pl{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:40px}.p{background:#1e293b;border:1px solid #334155;border-radius:16px;padding:28px}.p.f{border-color:#6366f1;transform:scale(1.03)}.p .nm{font-size:.8rem;text-transform:uppercase;color:#94a3b8;letter-spacing:1px;margin-bottom:8px}.p .pr{font-size:3rem;font-weight:700}.p .pr span{font-size:.9rem;color:#94a3b8;font-weight:400}.p ul{list-style:none;margin:24px 0;text-align:left}.p ul li{padding:8px 0;font-size:.85rem;color:#94a3b8;display:flex;align-items:center;gap:8px}.p ul li:before{content:"\\2713";color:#10b981;font-weight:700}.p .btn{display:block;padding:12px;border-radius:10px;background:transparent;border:1px solid #334155;color:#e2e8f0;font-weight:600;text-decoration:none;font-size:.85rem}.p.f .btn{background:#6366f1;color:#fff;border-color:#6366f1}.p .btn:hover{background:#6366f1;color:#fff}@media(max-width:700px){.pl{grid-template-columns:1fr}.p.f{transform:none}}</style></head><body><div class="w"><h1>Simple <span>Pricing</span></h1><p class="sub">No hidden fees. No surprises.</p><div class="tr"><span id="mo" class="act">Monthly</span><div class="tg" id="tg" onclick="tog()"><div class="k"></div></div><span id="yr">Yearly <span style="color:#10b981;font-size:.7rem">-20%</span></span></div><div class="pl" id="pl"></div><p style="color:#64748b;font-size:.8rem">All plans include a 14-day free trial.</p></div><script>var plans=[{n:"Starter",mo:19,yr:190,f:false,fe:["5 Projects","10GB Storage","Basic Support","Email notifications"]},{n:"Professional",mo:49,yr:490,f:true,fe:["Unlimited Projects","100GB Storage","Priority Support","Advanced Analytics","API Access","Custom Domains"]},{n:"Enterprise",mo:149,yr:1490,f:false,fe:["Unlimited Everything","Custom Integrations","Dedicated Manager","SLA 99.99%","SSO/SAML","Audit Logs"]}];var y=false;function rP(){document.getElementById("pl").innerHTML=plans.map(function(p){return'<div class="p'+(p.f?" f":"")+'"><div class="nm">'+p.n+'</div><div class="pr">$'+(y?p.yr:p.mo)+"<span>/"+(y?"yr":"mo")+'</span></div><ul>'+p.fe.map(function(f){return"<li>"+f+"</li>"}).join("")+'</ul><a href="#" class="btn">'+(p.f?"Get Started":"Learn More")+"</a></div>"}).join("")}window.tog=function(){y=!y;document.getElementById("tg").classList.toggle("act");document.getElementById("mo").classList.toggle("act");document.getElementById("yr").classList.toggle("act");rP()};rP()</script></body></html>
